-- Offline, synthetic schema. The report and canonical helpers are loaded separately.
create role anon;create role authenticated;create role service_role;
create schema icash_call_offer_private;create schema icash_seller_agreement_private;create schema icash_recorded_reception_private;
create table icash_accounts(id uuid primary key,owner_user_id uuid,bot_paused boolean default false);
create table icash_funding_orders(account_id uuid,mode text,state text);
create index on icash_funding_orders(account_id);
create table icash_screening_jobs(id uuid primary key,account_id uuid,snapshot jsonb default '{}');
create table icash_deal_files(id uuid primary key,account_id uuid,screening_id uuid,terms jsonb default '{}');
create table icash_text_threads(id uuid primary key,account_id uuid,deal_id uuid,party text default 'seller',paused boolean default false,manual_only boolean default false,ai_mode text default 'auto',retired_at timestamptz,sender text default '+15550000001',recipient text default '+15550000002');
create table icash_text_events(id text primary key,type text,payload jsonb);
create table icash_text_messages(id uuid primary key default gen_random_uuid(),account_id uuid,thread_id uuid,direction text,state text,created_at timestamptz default now(),provider_id text,event_id text,body text default 'Yes, I own it',last_delivery_at timestamptz,customer_author_id uuid);
create index on icash_text_messages(account_id,thread_id,created_at desc);
create table icash_seller_reply_progress(message_id uuid primary key,account_id uuid,thread_id uuid,state text,reason text,next_check_at timestamptz);
create table icash_text_ai_jobs(id uuid primary key default gen_random_uuid(),account_id uuid,thread_id uuid,message_id uuid unique,outgoing_id uuid,analysis jsonb default '{}',reply text);
create index on icash_text_ai_jobs(account_id,thread_id);
create table icash_seller_limited_text_replies(account_id uuid,thread_id uuid,source_id uuid primary key,message_id uuid);
create table icash_seller_text_replies(account_id uuid,thread_id uuid,source_id uuid primary key,message_id uuid);
create table icash_sms_seller_openings(account_id uuid,thread_id uuid,owner_reply_id uuid,interest_message_id uuid);
create index on icash_sms_seller_openings(account_id,thread_id);
create table icash_operation_spend(account_id uuid,operation_key text primary key,dispatched_at timestamptz);
create table icash_call_recordings(id uuid primary key default gen_random_uuid(),account_id uuid,screening_id uuid,party text default 'seller',call_sid text,dial_claimed_at timestamptz,operation_key text,contact_key text,conversation_id text);
create table icash_live_conversations(id uuid primary key default gen_random_uuid(),account_id uuid,screening_id uuid,operation_key text,contact_key text,party text default 'seller',conversation_id text,state text,result jsonb,created_at timestamptz default now(),completed_at timestamptz);
create index on icash_live_conversations(account_id,operation_key);
create table icash_call_offer_private.events(id uuid primary key default gen_random_uuid(),deal_id uuid,account_id uuid,call_key text,action text,state jsonb,created_at timestamptz default now());
create table icash_call_offer_private.offers(deal_id uuid primary key,account_id uuid,state jsonb,updated_at timestamptz default now());
create table icash_seller_agreement_private.inbound_bindings(session_id uuid primary key,account_id uuid,deal_id uuid);
create table icash_recorded_reception_private.sessions(id uuid primary key,account_id uuid,conversation_id text);
create table icash_signing_envelopes(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid,kind text,state text,test_mode boolean,provider_id text,terms_hash text,recipients jsonb,provider_evidence jsonb,updated_at timestamptz default now());
create index on icash_signing_envelopes(account_id,deal_id);
create table icash_live_callbacks(id uuid primary key default gen_random_uuid(),conversation_id uuid,account_id uuid,screening_id uuid,due_at timestamptz,state text,created_at timestamptz default now());
